#!/usr/bin/env bash
# tools/mkbig-repo.sh — generate a deterministic ≥30k-commit repo for the W2 perf smoke.
#
# Usage:  tools/mkbig-repo.sh [count] [dir]
#         count  trunk commits to generate (default 30000; each 100-commit chunk also
#                adds a one-commit side branch plus a merge, so the repo is larger)
#         dir    target directory (default /tmp/ggt-big); wiped and recreated
#
# Built with a single `git fast-import` stream (no node, no network, heredoc-free), so
# it finishes in seconds. The same shape is generated by `tests/perf.rs`; this script
# is for manual runs and the pty first-frame capture.
#
#   tools/mkbig-repo.sh
#   ( cd /tmp/ggt-big && "$OLDPWD/tools/pty-shot.sh" big-repo )
set -euo pipefail

count="${1:-30000}"
dir="${2:-/tmp/ggt-big}"
chunk=100

rm -rf "$dir"
mkdir -p "$dir"
git -C "$dir" init -q
# `git init` may default to `master`; pin HEAD so the repo has a born branch.
git -C "$dir" symbolic-ref HEAD refs/heads/main

{
  mark=0 main=0 time=1600000000 done=0 ci=0
  while [ "$done" -lt "$count" ]; do
    i=0
    while [ "$i" -lt "$chunk" ]; do
      mark=$((mark + 1))
      time=$((time + 1))
      msg="trunk $mark"
      printf 'commit refs/heads/main\nmark :%d\nauthor Perf <perf@example.com> %d +0000\ncommitter Perf <perf@example.com> %d +0000\ndata %d\n%s\n' \
        "$mark" "$time" "$time" "${#msg}" "$msg"
      if [ "$main" -gt 0 ]; then
        printf 'from :%d\n' "$main"
      fi
      main=$mark
      i=$((i + 1))
      done=$((done + 1))
    done

    side_base=$main
    side_ref="refs/heads/side-$ci"
    printf 'reset %s\nfrom :%d\n' "$side_ref" "$side_base"
    mark=$((mark + 1))
    time=$((time + 1))
    msg="side $ci"
    printf 'commit %s\nmark :%d\nauthor Perf <perf@example.com> %d +0000\ncommitter Perf <perf@example.com> %d +0000\ndata %d\n%s\nfrom :%d\n' \
      "$side_ref" "$mark" "$time" "$time" "${#msg}" "$msg" "$side_base"
    side=$mark

    mark=$((mark + 1))
    time=$((time + 1))
    msg="merge $ci"
    printf 'commit refs/heads/main\nmark :%d\nauthor Perf <perf@example.com> %d +0000\ncommitter Perf <perf@example.com> %d +0000\ndata %d\n%s\nfrom :%d\nmerge :%d\n' \
      "$mark" "$time" "$time" "${#msg}" "$msg" "$main" "$side"
    main=$mark
    ci=$((ci + 1))
  done
} | git -C "$dir" fast-import --quiet --force

total="$(git -C "$dir" rev-list --all --count)"
echo "generated $dir ($total commits, $(git -C "$dir" branch --list | wc -l) branches)"
